fn array_split(a: Vec<i32>) -> (Vec<i32>, Vec<i32>) {
    let len = a.len();

    if len == 0 {
        // Empty input -> two empty outputs
        return (Vec::new(), Vec::new());
    }

    if len == 1 {
        // Return either (empty, original) or (original, empty)
        // Both parts lengths sum to 1, and original length is not > 1, so no strict shorter constraint
        // Let's return (a.clone(), empty)
        return (a.clone(), Vec::new());
    }

    // len > 1: split in the middle to ensure both parts are strictly shorter
    let split_index = len / 2;

    // split_at returns (&[T], &[T]) slices; clone into Vec
    let (left_slice, right_slice) = a.split_at(split_index);
    (left_slice.to_vec(), right_slice.to_vec())
}